SELECT #{planId} as plan_id, c.device_id, c.device_name, b.device_mete_id, b.mete_name AS device_mete_name, a.instance_id, a.cruise_name AS instance_name, CASE WHEN cruise_type = 229 OR cruise_type = 230 THEN d.preset_id WHEN cruise_type = 228 OR cruise_type = 524 THEN e.inspection_id ELSE f.voice_device_id END AS position_id, CASE WHEN cruise_type = 229 OR cruise_type = 230 THEN d.preset_name WHEN cruise_type = 228 OR cruise_type = 524 THEN e.inspection_name ELSE f.voice_device_name END AS position_name, e.robot_id, a.cruise_type AS point_type FROM t_cruise_point_instance a LEFT JOIN t_std_devicemete b ON b.device_mete_id = a.device_mete_id LEFT JOIN t_std_device c ON c.device_id = a.device_id LEFT JOIN t_camera_preset d ON d.preset_id = a.cruise_id LEFT JOIN t_robot_inspection e ON e.inspection_id = a.cruise_id LEFT JOIN t_voice_device f ON f.voice_device_id = a.cruise_id WHERE a.instance_id IN (
#{instanceId, jdbcType=BIGINT}
)

